"   .. "ESP 세부 옵션은 단축키가 아니라 버튼 토글로 사용" });v461:CreateSection("💾 설정 저장 설명");v461:CreateParagraph({Title="저장 / 불러오기 / 전체 초기화",Content="💾 현재 설정 저장 = 지금 켜둔 토글 / 수치 / 키 설정을 파일로 저장\n"   .. "📂 저장된 설정 불러오기 = 마지막 저장값 적용\n"   .. "🔄 모든 설정 기본값으로 복원 = 모든 토글 OFF + 수치 기본값 + 키 기본값으로 전부 복원\n"   .. "일부 실행기는 writefile / readfile 미지원이라 저장이 안 될 수 있음" });v461:CreateSection("메인 탭 기능");v461:CreateParagraph({Title="플라이 / 달리기 / 점프 / FOV",Content="1. 플라이\n"   .. "- 토글로 켜고 끌 수 있음\n"   .. "- 설정한 플라이 키로도 바로 켜고 끌 수 있음\n"   .. "- W A S D 로 앞 / 왼쪽 / 뒤 / 오른쪽 이동\n"   .. "- Ctrl = 아래, Space = 위 이동\n"   .. "- 카메라 방향을 따라 이동함\n"   .. "- 슬라이더와 숫자 입력으로 속도 조절 가능\n\n"   .. "2. 달리기 속도\n"   .. "- 부드러운 가속형 방식으로 적용됨\n"   .. "- 슬라이더와 숫자 입력으로 속도 조절 가능\n\n"   .. "3. 무한 점프\n"   .. "- 토글을 켜면 점프를 계속 사용할 수 있음\n\n"   .. "4. 점프 높이\n"   .. "- 토글을 켜야 적용됨\n"   .. "- 슬라이더와 숫자 입력으로 높이 조절 가능\n\n"   .. "5. FOV 시야\n"   .. "- 슬라이더로 시야 범위 조절 가능" });v461:CreateSection("플레이어 탭 기능");v461:CreateParagraph({Title="ESP / 에임락 / 벽통과 / 투명화 / 텔레포트 / 3인칭 / 헤드리스 / 코블록스 / 텔레포트 툴 / 좌표 저장 복귀",Content="1. ESP\n"   .. "- 전체 표시 ON/OFF\n"   .. "- 박스 표시\n"   .. "- 체력바 표시\n"   .. "- 이름 표시\n"   .. "- 거리 표시\n"   .. "- 전체 강조 표시\n"   .. "- 전체 OFF\n\n"   .. "8. 에임락\n"   .. "- 토글 버튼 설정한 단축키로 ON / OFF 가능\n"   .. "- 우클릭 유지 중일 때만 FOV 안에 가장 가까운 대상을 추적함\n"   .. "- 에임 FOV = 인식 범위, 에임 강도 = 따라가는 속도 조절값\n"   .. "- 최대거리 = 너무 멀리 있는 대상 무시\n"   .. "- 타겟 부위 = Head / Body / Both 선택 가능\n"   .. "- 벽 뒤 무시 켜면 벽 뒤 대상은 에임락에서 제외됨\n"   .. "- 에임 설정 기본값 버튼을 누르면 관련 수치만 초기값으로 복원됨\n\n"   .. "9. 벽통과\n"   .. "- G 키 또는 토글 버튼으로 켜고 끌 수 있음\n\n"   .. "10. 투명화\n"   .. "- 플레이어를 버튼 또는 H 키로 켜고 끌 수 있음\n\n"   .. "11. 텔레포트\n"   .. "- 버튼 클릭 또는 없이도 클릭한 위치로 이동 가능\n\n"   .. "12. 3인칭\n"   .. "- 플레이어 탭에 3인칭 버튼으로 켜고 끌 수 있음\n"   .. "- 휠 마우스를 통해 1인칭 / 3인칭 자유 전환 가능\n"   .. "- 끌 때 카메라 중간에 원위 상태로 복원됨\n\n"   .. "13. 헤드리스\n"   .. "- 토글 버튼으로 켜고 끌 수 있음\n"   .. "- 해제는 OFF 후 리스폰이 필요할 수 있음\n\n"   .. "14. 코블록스\n"   .. "- 토글 버튼으로 켜고 끌 수 있음\n"   .. "- 완전히 끄려면 OFF 후 리스폰이 필요할 수 있음\n\n"   .. "15. 텔레포트 툴\n"   .. "- 버튼 누르면 가방에 TP Tool 지급\n"   .. "- 툴 장착 후 클릭한 위치로 이동\n\n"   .. "16. 현재 좌표 저장 / 저장 좌표 복귀\n"   .. "- 현재 위치 저장 후 다시 복귀 가능" });v461:CreateSection("TP / Follow 탭 기능");v461:CreateParagraph({Title="플레이어 선택 / TP / 따라가기",Content="1. 플레이어 목록은 나와 가까운 순서대로 위에 표시됨\n"   .. "2. 목록에서 표시이름 (@사용자명) 형태로 확인 가능\n"   .. "3. 선택한 플레이어는 Z 키로 바로 TP 가능\n"   .. "4. TP 버튼을 눌러도 선택 플레이어에게 바로 이동 가능\n"   .. "5. 따라가기 토글을 켜면 선택한 플레이어를 계속 따라감" });v461:CreateSection("아이템 기능");v461:CreateParagraph({Title="아이템 가져오기",Content="버튼을 누르면 아이템 지급 스크립트가 실행됨\n"   .. "끄기 버튼을 누르면 아이템 가져오기 UI와 지급된 아이템을 정리함" });v461:CreateSection("유용한 기능");v461:CreateParagraph({Title="안티 잠수 / 넉백 방지 / 풀라이트 / FPS 최적화 / 고화질",Content="1. 안티 잠수\n"   .. "- 잠수 상태에서도 자동으로 입력을 보내 튕김을 방지함\n\n"   .. "2. 넉백 방지\n"   .. "- 공격이나 폭발로 밀려나는 것을 방지함\n\n"   .. "3. 풀라이트\n"   .. "- 맵을 항상 밝게 유지하여 시야를 확보함\n\n"   .. "4. FPS 최적화 모드\n"   .. "- 그림자, 광원, 파티클, 물 반사 등을 줄여 프레임을 올리는 기능\n"   .. "- 켜면 고화질 모드는 자동으로 꺼짐\n"   .. "- 끄면 원래 그래픽 상태로 복원됨\n\n"   .. "5. 고화질 모드\n"   .. "- 조명, 그림자, 색감 효과를 강화해서 화면이 더 진하게 보이게 함\n"   .. "- 켜면 FPS 최적화 모드는 자동으로 꺼짐\n"   .. "- 끄면 원래 그래픽 상태로 복원됨" });v461:CreateSection("연락");v461:CreateParagraph({Title="디스코드",Content="디스코드 ID : jornix0318"});v169();applyJumpHeight();applyCameraFOV();v154();v164(false);v83(true);v145("RNX HUB","Korea",143 -(43 + 96) );end local function v214(v466) local v467=v9:FindFirstChild("PlayerGui");if  not v467 then if v466 then v466();end return;end local v468=Instance.new("ScreenGui");v468.Name="RNXHubStartupSplash";v468.ResetOnSpawn=false;v468.IgnoreGuiInset=true;v468.ZIndexBehavior=Enum.ZIndexBehavior.Sibling;v468.DisplayOrder=999999;v468.Parent=v467;local v476=Instance.new("Frame");v476.Size=UDim2.fromScale(1,4 -3 );v476.BackgroundColor3=Color3.fromRGB(0 -0 ,0 + 0 ,0 + 0 );v476.BackgroundTransparency=1 -0 ;v476.Parent=v468;local v481=Instance.new("ImageLabel");v481.Name="Vignette";v481.Size=UDim2.fromScale(1.25 + 0 ,1.25);v481.Position=UDim2.fromScale(0.5 -0 ,0.5 + 0 );v481.AnchorPoint=Vector2.new(0.5,0.5 + 0 );v481.Backgro